package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.MaxSeriesVO;

class MaxSeriesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of max series of observed source")
  void test_max_series_value_holder_assign_plain_value() {
    Object holder = new Object();
    MaxSeriesValueHolder<Object> value = new MaxSeriesValueHolder<>(holder);
    Assertions.assertSame(holder, value.maxSeries(1), "Setters must return the holder");
    Assertions.assertTrue(value.getMaxSeriesValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getMaxSeries().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.maxSeriesNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getMaxSeriesValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getMaxSeries().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of max series of observed source")
  void test_max_series_value_holder_assign_value_object() {
    Object holder = new Object();
    MaxSeriesValueHolder<Object> value = new MaxSeriesValueHolder<>(holder);
    MaxSeriesVO vo = MaxSeriesVO.from(1);
    Assertions.assertFalse(value.getMaxSeriesValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.maxSeries(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMaxSeriesValue().orElseThrow());
    Assertions.assertSame(holder, value.maxSeries(Optional.empty()));
    Assertions.assertFalse(value.getMaxSeriesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.maxSeries(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMaxSeriesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of max series of observed source against the original")
  void test_max_series_value_holder_read() {
    Object holder = new Object();
    MaxSeriesValueHolder<Object> value = new MaxSeriesValueHolder<>(holder);
    MaxSeriesVO vo = MaxSeriesVO.from(1);
    MaxSeriesVO other = MaxSeriesVO.from(1);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getMaxSeriesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMaxSeries(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readMaxSeries(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.maxSeries(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMaxSeries(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMaxSeries(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of max series of observed source")
  void test_max_series_value_holder_unset() {
    Object holder = new Object();
    MaxSeriesValueHolder<Object> value = new MaxSeriesValueHolder<>(holder);
    MaxSeriesVO vo = MaxSeriesVO.from(1);
    value.maxSeries(vo);
    Assertions.assertSame(holder, value.unsetMaxSeriesIfMatches("maxSeries_other"));
    Assertions.assertTrue(value.getMaxSeriesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMaxSeriesIfMatches("maxSeries"));
    Assertions.assertFalse(value.getMaxSeriesValue().isPresent(),
        "The field name must clear the value");
    value.maxSeries(vo);
    Assertions.assertSame(holder, value.unsetMaxSeries());
    Assertions.assertFalse(value.getMaxSeriesValue().isPresent(), "Unset must clear the value");
  }
}
